    static func toned(_ base: String, _ tone: SkinTone) -> String {
        let modifier = tone.rawValue
        guard let scalar = base.unicodeScalars.first else { return base }
        let head = String(scalar)
        let tail = base.unicodeScalars.dropFirst()
        var rebuilt = head + modifier
        var droppedLeadFE0F = false
        for s in tail {
            if !droppedLeadFE0F && s == "\u{FE0F}" {
                droppedLeadFE0F = true
                continue
            }
            rebuilt.unicodeScalars.append(s)
        }
        return rebuilt
    }

    static func search(_ query: String) -> [String] {
        let normalized = query.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return [] }
        let tokens = normalized.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        guard !tokens.isEmpty else { return [] }

        var seen = Set<String>()
        var results: [String] = []

        for (emoji, terms) in keywords {
            let allMatch = tokens.allSatisfy { token in
                terms.contains { $0.hasPrefix(token) }
            }
            if allMatch && seen.insert(emoji).inserted {
                results.append(emoji)
            }
        }

        guard results.isEmpty else { return results }

        for (name, emojis) in categories {
            let cat = name.lowercased()
            guard tokens.allSatisfy({ cat.contains($0) }) else { continue }
            for emoji in emojis where seen.insert(emoji).inserted {
                results.append(emoji)
            }
        }

        return results
    }
